        self._request = request           # HttpRequest Django
        self.parsers = parsers or ()
        self.authenticators = authenticators or ()
        self._data = Empty
        self._files = Empty
        self._full_data = Empty
        self._user = Empty
        self._auth = Empty

    @property
    def data(self):
        if not _hasattr(self, "_full_data"):
            self._load_data_and_files()
        return self._full_data

    @property
    def query_params(self):
        return self._request.GET

    @property
    def user(self):
        if not _hasattr(self, "_user"):
            self._authenticate()
        return self._user

    @property
    def auth(self):
        if not _hasattr(self, "_auth"):
            self._authenticate()
