def get(self, request):
    # اینجا request.data فراخوانی نمی‌شود — پارسر اجرا نمی‌شود
    return Response({"ok": True})

# فقط وقتی به data دسترسی داشتیم، پارسر اجرا می‌شود
def post(self, request):
    data = request.data   # پارسر اینجا اجرا می‌شود
    return Response(data)

def _authenticate(self):
    for authenticator in self.authenticators:
        try:
            user_auth_tuple = authenticator.authenticate(self)
        except APIException:
            self._not_authenticated()
            raise

        if user_auth_tuple is not None:
            self._authenticator = authenticator
            self.user, self.auth = user_auth_tuple
            return

    self._not_authenticated()


def _not_authenticated(self):
    self._authenticator = None
    if api_settings.UNAUTHENTICATED_USER:
        self.user = api_settings.UNAUTHENTICATED_USER()  # AnonymousUser
    else:
        self.user = None
    self.auth = None

from rest_framework.request import Request


class TenantRequest(Request):
    """Request با tenant از هدر."""

    @property
    def tenant(self):
        if not hasattr(self, "_tenant"):
            slug = self.headers.get("X-Tenant")
            self._tenant = Tenant.objects.filter(slug=slug).first() if slug else None
        return self._tenant


# در View
class MyView(APIView):
    def initialize_request(self, request, *args, **kwargs):
        request = super().initialize_request(request, *args, **kwargs)
        request.__class__ = TenantRequest
        return request

